CURLcode escape_eob_markers(struct connectdata *conn, ssize_t nread) {
  char *scratch = NULL;
  size_t scratch_len = 0;
  size_t i = 0, j = 0;
  bool trailing_crlf = FALSE;

  if (nread <= 0) {
    return CURLE_OK;
  }

  scratch = malloc(nread * 2 + 1);
  if (!scratch) {
    return CURLE_OUT_OF_MEMORY;
  }

  for (i = 0; i < (size_t)nread; i++) {
    if (i + 1 < (size_t)nread && conn->uploadbuf[i] == '\r' && conn->uploadbuf[i + 1] == '\n') {
      scratch[j++] = '\r';
      scratch[j++] = '\n';
      scratch[j++] = '.';
      i++;
      trailing_crlf = TRUE;
    } else {
      scratch[j++] = conn->uploadbuf[i];
    }
  }

  if (trailing_crlf) {
    scratch[j++] = '.';
  }

  if (conn->scratch_buffer) {
    free(conn->scratch_buffer);
  }

  conn->scratch_buffer = scratch;
  conn->scratch_len = j;

  return CURLE_OK;
}
